import{_ as t,c as n,j as e,a as l,o as r}from"./chunks/framework.CqbvlPrP.js";const u=JSON.parse('{"title":"第二百四十三章 易碎、易坏的法","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/243第二百四十三章 易碎、易坏的法.md","filePath":"meditation/巴利文大藏经/243第二百四十三章 易碎、易坏的法.md"}'),_={name:"meditation/巴利文大藏经/243第二百四十三章 易碎、易坏的法.md"};function o(s,a,i,d,p,c){return r(),n("div",null,a[0]||(a[0]=[e("h1",{id:"第二百四十三章-易碎、易坏的法",tabindex:"-1"},[l("第二百四十三章 易碎、易坏的法 "),e("a",{class:"header-anchor",href:"#第二百四十三章-易碎、易坏的法","aria-label":'Permalink to "第二百四十三章 易碎、易坏的法"'},"​")],-1),e("p",null,"完全读懂巴利文大藏经",-1),e("p",null,"相应部22相应32经/易坏的经(蕴相应/蕴篇/修多罗)",-1),e("p",null,"有个时候，佛陀住在舍卫城的祇树林给孤独园，有一天，佛陀对出家弟子们说：“比丘们（出家人）！如来现在要教导你们，什么是世间易碎、易坏的法？什么是世间不易碎、不易坏的法？你们要认真的听，你们要仔细的思考，如来现在要开始说法了。”",-1),e("p",null,"出家弟子们回答：“世尊，我们会认真听您说法的，我们会仔细思考的，恭请世尊您为我们说法。”",-1),e("p",null,"佛陀说：“比丘们！物质事物、物质身体、感受、念想、行为、认识、分别、判断随时在变化，无法永远存在，无法永恒保持不变，是会衰败、灭亡、消失的法，是会由此让众生生起无数念想，让众生产生无数烦恼和痛苦的法，是易碎、易坏的法。",-1),e("p",null,"比丘们！熄灭、平息、除灭对物质事物、物质身体、感受、念想、行为、认识、分别、判断的贪欲、渴爱，就不会执着和挂念物质事物、物质身体、感受、念想、行为、认识、分别、判断，就不会由此生起无数的念想，就不会由此产生无数的烦恼和痛苦，熄灭、平息、除灭对物质事物、物质身体、感受、念想、行为、认识、分别、判断的贪欲、渴爱，就能让内心保持长久的清净安宁，这就是让自己不再执着和挂念物质事物、物质身体、感受、念想、行为、认识、分别、判断，从一切烦恼和痛苦中永远解脱出来，不易碎、不易坏的法。”",-1),e("p",null,"佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。",-1)]))}const f=t(_,[["render",o]]);export{u as __pageData,f as default};
